BFS/DFS from start; mark visited; if index value points to target, return True.

```python
from collections import deque

def can_reach(arr, start):
    q = deque([start])
    seen = {start}
    while q:
        i = q.popleft()
        if arr[i] == 0:
            return True
        for j in (i - arr[i], i + arr[i]):
            if 0 <= j < len(arr) and j not in seen:
                seen.add(j)
                q.append(j)
    return False
